import numpy as np
from itertools import product

def allowed_N(structure, n_max=60):
    """Sorted distinct values of h^2 + k^2 + l^2 that give a reflection."""
    out = set()
    for h, k, l in product(range(8), repeat=3):
        N = h * h + k * k + l * l
        if N == 0 or N > n_max:
            continue
        even = [i % 2 == 0 for i in (h, k, l)]
        if structure == "BCC" and (h + k + l) % 2:
            continue
        if structure in ("FCC", "diamond") and not (all(even) or not any(even)):
            continue
        if structure == "diamond" and all(even) and (h + k + l) % 4:
            continue
        out.add(N)
    return sorted(out)

def identify_cubic(two_theta, wavelength):
    s2 = np.sin(np.radians(np.asarray(two_theta, float)) / 2) ** 2
    best = None
    for structure in ("SC", "BCC", "FCC", "diamond"):
        N = np.array(allowed_N(structure)[:len(s2)], float)
        mismatch = np.max(np.abs(s2 / s2[0] - N / N[0]))
        a = float(np.mean(wavelength / 2 * np.sqrt(N / s2)))
        if best is None or mismatch < best[0]:
            best = (mismatch, structure, a)
    return best[1], best[2]

